CREATE TABLE IF NOT EXISTS form_list (listID INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, sortOrder INTEGER NOT NULL DEFAULT 0, UNIQUE(name COLLATE NOCASE));
CREATE TABLE IF NOT EXISTS form_list_item (itemID INTEGER PRIMARY KEY AUTOINCREMENT, listID INTEGER NOT NULL REFERENCES form_list(listID) ON DELETE CASCADE, text TEXT NOT NULL, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS form_setting (key TEXT PRIMARY KEY NOT NULL, value TEXT);
CREATE TABLE IF NOT EXISTS formcontrols_schema (schemaID INTEGER PRIMARY KEY UNIQUE NOT NULL, version NUMERIC (12) UNIQUE NOT NULL);
CREATE INDEX IF NOT EXISTS idx_form_list_item ON form_list_item(listID, sortOrder);
